//! Import de podcast : récupération d'un flux RSS et téléchargement des médias.
//!
//! Premier accès HTTP **externe** assumé du projet (les podcasts vivent sur le web,
//! contrairement à ComfyUI/XTTS qui restent locaux). On valide donc explicitement le
//! schéma (`http`/`https`) et on plafonne la taille des téléchargements.

use crate::support::user_message;
use crate::support::user_message::codes;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::time::Duration;

use serde::Serialize;
use sha2::{Digest, Sha256};

use crate::support::network::http_client;
use crate::support::paths::path_for_frontend;

const MAX_FEED_BYTES: u64 = 10 * 1024 * 1024; // 10 Mo
const MAX_MEDIA_BYTES: u64 = 300 * 1024 * 1024; // 300 Mo
const FEED_TIMEOUT: Duration = Duration::from_secs(30);
const MEDIA_TIMEOUT: Duration = Duration::from_secs(300);
const USER_AGENT: &str = "StoryStudio/0.9 (podcast import)";

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PodcastEpisode {
    pub id: String,
    pub title: String,
    pub audio_url: String,
    pub mime_type: Option<String>,
    pub pub_date: Option<String>,
    pub duration: Option<String>,
    pub description: Option<String>,
    pub image_url: Option<String>,
    pub size_bytes: Option<u64>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PodcastFeed {
    pub title: String,
    pub image_url: Option<String>,
    pub episodes: Vec<PodcastEpisode>,
}

fn validate_remote_url(url: &str) -> Result<reqwest::Url, String> {
    let parsed = reqwest::Url::parse(url.trim()).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::PODCAST_INVALID_URL)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "URL invalide : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    match parsed.scheme() {
        "http" | "https" => Ok(parsed),
        other => Err({
            let _msg_other = (other).to_string();
            user_message::UserMessage::new(codes::PODCAST_URL_SCHEME_REFUSED)
                .param("scheme", user_message::transport_param(_msg_other.clone()))
                .with_detail(format!(
                    "Schéma d'URL non autorisé : {_msg_other} (seuls http et https le sont).",
                    _msg_other = user_message::transport_detail(&_msg_other),
                ))
                .into_transport()
        }),
    }
}

/// Lit un `Read` en imposant une taille maximale.
fn read_limited<R: Read>(mut reader: R, max: u64) -> Result<Vec<u8>, String> {
    let mut buf = Vec::new();
    reader
        .by_ref()
        .take(max + 1)
        .read_to_end(&mut buf)
        .map_err(|e| {
            let _msg_error = (e).to_string();
            user_message::UserMessage::new(codes::PODCAST_CONTENT_READ_FAILED)
                .param("error", user_message::transport_param(_msg_error.clone()))
                .with_detail(format!(
                    "Lecture du contenu impossible : {_msg_error}",
                    _msg_error = user_message::transport_detail(&_msg_error)
                ))
                .into_transport()
        })?;
    if buf.len() as u64 > max {
        return Err({
            let _msg_max = (max).to_string();
            user_message::UserMessage::new(codes::PODCAST_CONTENT_TOO_LARGE_BYTES)
                .param("max", user_message::transport_param(_msg_max.clone()))
                .with_detail(format!(
                    "Contenu trop volumineux (> {_msg_max} octets).",
                    _msg_max = user_message::transport_detail(&_msg_max)
                ))
                .into_transport()
        });
    }
    Ok(buf)
}

pub fn fetch_feed(url: &str) -> Result<PodcastFeed, String> {
    let parsed = validate_remote_url(url)?;
    let client = http_client(FEED_TIMEOUT)?;
    let response = client
        .get(parsed)
        .header(reqwest::header::USER_AGENT, USER_AGENT)
        .send()
        .map_err(|e| {
            let _msg_error = (e).to_string();
            user_message::UserMessage::new(codes::PODCAST_FEED_FETCH_FAILED)
                .param("error", user_message::transport_param(_msg_error.clone()))
                .with_detail(format!(
                    "Impossible de récupérer le flux : {_msg_error}",
                    _msg_error = user_message::transport_detail(&_msg_error)
                ))
                .into_transport()
        })?;
    if !response.status().is_success() {
        return Err({
            let _msg_response = (response.status()).to_string();
            user_message::UserMessage::new(codes::PODCAST_FEED_HTTP_ERROR)
                .param(
                    "response",
                    user_message::transport_param(_msg_response.clone()),
                )
                .with_detail(format!(
                    "Le flux a répondu HTTP {_msg_response}.",
                    _msg_response = user_message::transport_detail(&_msg_response)
                ))
                .into_transport()
        });
    }
    let bytes = read_limited(response, MAX_FEED_BYTES)?;
    let text = String::from_utf8_lossy(&bytes);
    // Certains flux exposent un BOM UTF-8 ou des espaces avant <?xml> : roxmltree les refuse.
    let cleaned = text.trim_start_matches('\u{feff}').trim_start();
    parse_feed(cleaned)
}

pub fn download_media(output_dir: &Path, url: &str, file_name: &str) -> Result<String, String> {
    let parsed = validate_remote_url(url)?;
    let client = http_client(MEDIA_TIMEOUT)?;
    let response = client
        .get(parsed.clone())
        .header(reqwest::header::USER_AGENT, USER_AGENT)
        .send()
        .map_err(|e| {
            let _msg_error = (e).to_string();
            user_message::UserMessage::new(codes::PODCAST_DOWNLOAD_IMPOSSIBLE)
                .param("error", user_message::transport_param(_msg_error.clone()))
                .with_detail(format!(
                    "Téléchargement impossible : {_msg_error}",
                    _msg_error = user_message::transport_detail(&_msg_error)
                ))
                .into_transport()
        })?;
    if !response.status().is_success() {
        return Err({
            let _msg_response = (response.status()).to_string();
            user_message::UserMessage::new(codes::PODCAST_DOWNLOAD_HTTP_ERROR)
                .param(
                    "response",
                    user_message::transport_param(_msg_response.clone()),
                )
                .with_detail(format!(
                    "Le serveur a répondu HTTP {_msg_response}.",
                    _msg_response = user_message::transport_detail(&_msg_response)
                ))
                .into_transport()
        });
    }

    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .and_then(|s| s.split(';').next())
        .map(|s| s.trim().to_ascii_lowercase());
    let ext = extension_for(content_type.as_deref(), &parsed);
    let stem = sanitize_stem(file_name);

    fs::create_dir_all(output_dir).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::PODCAST_TEMP_FOLDER_CREATE_FAILED)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "Création du dossier temporaire impossible : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    let dest = unique_path(output_dir, &stem, &ext);

    let bytes = read_limited(response, MAX_MEDIA_BYTES)?;
    if bytes.is_empty() {
        return Err(
            user_message::UserMessage::new(codes::PODCAST_DOWNLOADED_FILE_EMPTY)
                .with_detail("Fichier téléchargé vide.".to_string())
                .into_transport(),
        );
    }
    fs::write(&dest, &bytes).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::PODCAST_FILE_WRITE_FAILED)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "Écriture du fichier impossible : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    Ok(path_for_frontend(&dest))
}

fn parse_feed(xml: &str) -> Result<PodcastFeed, String> {
    let doc = roxmltree::Document::parse(xml).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::PODCAST_UNREADABLE_RSS_FEED)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "Flux RSS illisible : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    let channel = doc
        .root_element()
        .descendants()
        .find(|n| n.is_element() && n.tag_name().name() == "channel")
        .ok_or_else(|| {
            user_message::UserMessage::new(codes::PODCAST_FEED_CHANNEL_MISSING)
                .with_detail("Flux invalide : aucun <channel> RSS trouvé.".to_string())
                .into_transport()
        })?;

    let title = child_text(&channel, "title").unwrap_or_else(|| "Podcast".to_string());
    let feed_image = node_image(&channel);

    let mut episodes = Vec::new();
    for (index, item) in channel
        .children()
        .filter(|n| n.is_element() && n.tag_name().name() == "item")
        .enumerate()
    {
        if let Some(episode) = parse_item(&item, index, feed_image.as_deref()) {
            episodes.push(episode);
        }
    }

    dedupe_episode_ids(&mut episodes);

    if episodes.is_empty() {
        return Err(
            user_message::UserMessage::new(codes::PODCAST_FEED_EPISODES_MISSING)
                .with_detail("Aucun épisode audio trouvé dans ce flux.".to_string())
                .into_transport(),
        );
    }

    Ok(PodcastFeed {
        title,
        image_url: feed_image,
        episodes,
    })
}

fn parse_item(
    item: &roxmltree::Node,
    index: usize,
    feed_image: Option<&str>,
) -> Option<PodcastEpisode> {
    let enclosure = child_by_local(item, "enclosure")?;
    let audio_url = enclosure.attribute("url").map(str::trim).unwrap_or("");
    if audio_url.is_empty() {
        return None;
    }
    let mime_type = enclosure
        .attribute("type")
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty());
    let size_bytes = enclosure
        .attribute("length")
        .and_then(|s| s.trim().parse::<u64>().ok())
        .filter(|&n| n > 0);

    let title = child_text(item, "title").unwrap_or_else(|| format!("Épisode {}", index + 1));
    let pub_date = child_text(item, "pubDate");
    let duration = child_text(item, "duration"); // itunes:duration (nom local)
    let description = child_text(item, "description").or_else(|| child_text(item, "summary"));
    let image_url = node_image(item).or_else(|| feed_image.map(str::to_string));
    let id = stable_episode_id(item, audio_url);

    Some(PodcastEpisode {
        id,
        title,
        audio_url: audio_url.to_string(),
        mime_type,
        pub_date,
        duration,
        description,
        image_url,
        size_bytes,
    })
}

/// Uses the RSS item GUID when available; enclosure URLs can change when a host migrates media.
/// SHA-256 keeps identifiers compact and stable across platforms and Rust versions.
fn stable_episode_id(item: &roxmltree::Node, audio_url: &str) -> String {
    let (kind, value) = child_text(item, "guid")
        .map(|guid| ("guid", guid))
        .unwrap_or_else(|| ("url", audio_url.to_string()));
    format!("{}:{:x}", kind, Sha256::digest(value.as_bytes()))
}

/// Garantit l'unicité des identifiants du flux. Les flux sont classés du plus récent au plus
/// ancien : la dernière occurrence (la plus ancienne) d'un identifiant le conserve, et les autres
/// reçoivent un identifiant dérivé de l'identifiant + URL audio, puis + rang compté depuis la fin
/// du flux si l'URL est aussi identique. Ajouter des items en tête ne change donc aucun
/// identifiant existant.
fn dedupe_episode_ids(episodes: &mut [PodcastEpisode]) {
    let mut used: std::collections::HashSet<String> =
        episodes.iter().map(|e| e.id.clone()).collect();
    let mut seen = std::collections::HashSet::new();
    let mut collisions: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for episode in episodes.iter_mut().rev() {
        if seen.insert(episode.id.clone()) {
            continue;
        }
        let kind = episode.id.split(':').next().unwrap_or("guid").to_string();
        let rank = collisions.entry(episode.id.clone()).or_insert(0);
        let new_id = loop {
            let material = if *rank == 0 {
                format!("{}\n{}", episode.id, episode.audio_url)
            } else {
                format!("{}\n{}\n{}", episode.id, episode.audio_url, *rank)
            };
            *rank += 1;
            let candidate = format!("{}:{:x}", kind, Sha256::digest(material.as_bytes()));
            if !used.contains(&candidate) {
                break candidate;
            }
        };
        used.insert(new_id.clone());
        seen.insert(new_id.clone());
        episode.id = new_id;
    }
}

/// Premier enfant élément portant ce nom local (namespace ignoré, pour gérer iTunes).
fn child_by_local<'a, 'input>(
    parent: &roxmltree::Node<'a, 'input>,
    local: &str,
) -> Option<roxmltree::Node<'a, 'input>> {
    parent
        .children()
        .find(|c| c.is_element() && c.tag_name().name() == local)
}

fn child_text(parent: &roxmltree::Node, local: &str) -> Option<String> {
    child_by_local(parent, local)
        .and_then(|n| n.text())
        .map(|t| t.trim().to_string())
        .filter(|s| !s.is_empty())
}

/// Image d'un nœud channel/item : `itunes:image href` en priorité, sinon `<image><url>`.
fn node_image(node: &roxmltree::Node) -> Option<String> {
    if let Some(img) = node
        .children()
        .find(|c| c.is_element() && c.tag_name().name() == "image" && c.has_attribute("href"))
    {
        if let Some(href) = img
            .attribute("href")
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            return Some(href.to_string());
        }
    }
    if let Some(img) = child_by_local(node, "image") {
        if let Some(url) = child_text(&img, "url") {
            return Some(url);
        }
    }
    None
}

fn extension_for(content_type: Option<&str>, url: &reqwest::Url) -> String {
    if let Some(ct) = content_type {
        let mapped = match ct {
            "audio/mpeg" | "audio/mp3" => Some("mp3"),
            "audio/mp4" | "audio/x-m4a" | "audio/m4a" => Some("m4a"),
            "audio/aac" => Some("aac"),
            "audio/ogg" | "application/ogg" => Some("ogg"),
            "audio/wav" | "audio/x-wav" | "audio/wave" => Some("wav"),
            "audio/flac" | "audio/x-flac" => Some("flac"),
            "audio/webm" | "video/webm" => Some("webm"),
            "image/jpeg" => Some("jpg"),
            "image/png" => Some("png"),
            "image/webp" => Some("webp"),
            "image/gif" => Some("gif"),
            "image/bmp" => Some("bmp"),
            _ => None,
        };
        if let Some(ext) = mapped {
            return ext.to_string();
        }
    }
    if let Some(last) = url.path_segments().and_then(|mut s| s.next_back()) {
        if let Some(dot) = last.rfind('.') {
            let clean: String = last[dot + 1..]
                .chars()
                .take_while(|c| c.is_ascii_alphanumeric())
                .collect();
            if !clean.is_empty() && clean.len() <= 5 {
                return clean.to_ascii_lowercase();
            }
        }
    }
    "mp3".to_string()
}

fn sanitize_stem(name: &str) -> String {
    let mut out: String = name
        .chars()
        .map(|c| {
            if c.is_alphanumeric() || matches!(c, '-' | '_' | ' ') {
                c
            } else {
                '_'
            }
        })
        .collect();
    out = out.trim().to_string();
    if out.chars().count() > 80 {
        out = out.chars().take(80).collect::<String>().trim().to_string();
    }
    if out.is_empty() {
        out = "episode".to_string();
    }
    out
}

fn unique_path(dir: &Path, stem: &str, ext: &str) -> PathBuf {
    let mut candidate = dir.join(format!("{}.{}", stem, ext));
    let mut counter = 1;
    while candidate.exists() {
        candidate = dir.join(format!("{}-{}.{}", stem, counter, ext));
        counter += 1;
    }
    candidate
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:itunes="http://www.itunes.com/dtds/podcast-1.0.dtd">
  <channel>
    <title>Mon Podcast</title>
    <itunes:image href="https://example.com/cover.jpg"/>
    <item>
      <title>Episode 1</title>
      <pubDate>Mon, 01 Jan 2024 10:00:00 +0000</pubDate>
      <itunes:duration>00:12:34</itunes:duration>
      <enclosure url="https://example.com/ep1.mp3" type="audio/mpeg" length="123456"/>
      <itunes:image href="https://example.com/ep1.jpg"/>
      <description>Premier episode</description>
    </item>
    <item>
      <title>Episode 2</title>
      <enclosure url="https://example.com/ep2.mp3" type="audio/mpeg"/>
    </item>
    <item>
      <title>Sans audio</title>
    </item>
  </channel>
</rss>"#;

    #[test]
    fn parses_channel_and_episodes() {
        let feed = parse_feed(SAMPLE).expect("parse");
        assert_eq!(feed.title, "Mon Podcast");
        assert_eq!(
            feed.image_url.as_deref(),
            Some("https://example.com/cover.jpg")
        );
        // L'item sans enclosure est ignoré.
        assert_eq!(feed.episodes.len(), 2);

        let ep1 = &feed.episodes[0];
        assert_eq!(ep1.title, "Episode 1");
        assert_eq!(ep1.audio_url, "https://example.com/ep1.mp3");
        assert_eq!(ep1.mime_type.as_deref(), Some("audio/mpeg"));
        assert_eq!(ep1.duration.as_deref(), Some("00:12:34"));
        assert_eq!(ep1.size_bytes, Some(123456));
        assert_eq!(
            ep1.image_url.as_deref(),
            Some("https://example.com/ep1.jpg")
        );
        assert_eq!(ep1.description.as_deref(), Some("Premier episode"));

        // ep2 hérite de l'image du flux.
        assert_eq!(
            feed.episodes[1].image_url.as_deref(),
            Some("https://example.com/cover.jpg")
        );
    }

    #[test]
    fn rejects_non_rss() {
        assert!(parse_feed("<html><body>nope</body></html>").is_err());
    }

    #[test]
    fn rejects_feed_without_audio() {
        let xml = r#"<rss version="2.0"><channel><title>x</title><item><title>a</title></item></channel></rss>"#;
        assert!(parse_feed(xml).is_err());
    }

    #[test]
    fn guid_keeps_episode_identity_when_enclosure_url_changes() {
        let first = r#"<rss version="2.0"><channel><title>x</title><item><guid>episode-42</guid><enclosure url="https://old.example/42.mp3" type="audio/mpeg"/></item></channel></rss>"#;
        let migrated = r#"<rss version="2.0"><channel><title>x</title><item><guid>episode-42</guid><enclosure url="https://cdn.example/episode/42.mp3" type="audio/mpeg"/></item></channel></rss>"#;
        let first_id = &parse_feed(first).expect("parse first feed").episodes[0].id;
        let migrated_id = &parse_feed(migrated).expect("parse migrated feed").episodes[0].id;

        assert_eq!(first_id, migrated_id);
        assert!(first_id.starts_with("guid:"));
    }

    #[test]
    fn guid_distinguishes_episodes_with_the_same_enclosure_url() {
        let feed = r#"<rss version="2.0"><channel><title>x</title><item><guid>episode-a</guid><enclosure url="https://example.com/audio.mp3" type="audio/mpeg"/></item><item><guid>episode-b</guid><enclosure url="https://example.com/audio.mp3" type="audio/mpeg"/></item></channel></rss>"#;
        let parsed = parse_feed(feed).expect("parse feed");

        assert_ne!(parsed.episodes[0].id, parsed.episodes[1].id);
    }

    #[test]
    fn enclosure_url_fallback_is_stable_when_guid_is_missing() {
        let feed = r#"<rss version="2.0"><channel><title>x</title><item><enclosure url="https://example.com/audio.mp3" type="audio/mpeg"/></item></channel></rss>"#;
        let first_id = &parse_feed(feed).expect("parse first feed").episodes[0].id;
        let second_id = &parse_feed(feed).expect("parse second feed").episodes[0].id;

        assert_eq!(first_id, second_id);
        assert!(first_id.starts_with("url:"));
    }

    fn feed_ids(items: &str) -> Vec<String> {
        let xml = format!(
            r#"<rss version="2.0"><channel><title>x</title>{}</channel></rss>"#,
            items
        );
        parse_feed(&xml)
            .expect("parse feed")
            .episodes
            .into_iter()
            .map(|e| e.id)
            .collect()
    }

    fn item(guid: Option<&str>, url: &str) -> String {
        let guid = guid
            .map(|g| format!("<guid>{g}</guid>"))
            .unwrap_or_default();
        format!(r#"<item>{guid}<enclosure url="{url}" type="audio/mpeg"/></item>"#)
    }

    #[test]
    fn unique_guid_id_is_unchanged() {
        let ids = feed_ids(&item(Some("g1"), "https://e.com/a.mp3"));
        let expected = format!("guid:{:x}", Sha256::digest(b"g1"));
        assert_eq!(ids, vec![expected]);
    }

    #[test]
    fn duplicate_guid_gives_distinct_stable_ids() {
        let items = [
            item(Some("dup"), "https://e.com/a.mp3"),
            item(Some("dup"), "https://e.com/b.mp3"),
            item(Some("dup"), "https://e.com/c.mp3"),
        ]
        .concat();
        let ids = feed_ids(&items);
        let unique: std::collections::HashSet<_> = ids.iter().collect();
        assert_eq!(unique.len(), 3);
        assert_eq!(ids[2], format!("guid:{:x}", Sha256::digest(b"dup")));
        assert_eq!(ids, feed_ids(&items));
    }

    #[test]
    fn duplicate_guid_and_url_gives_distinct_stable_ids() {
        let items = [
            item(Some("dup"), "https://e.com/a.mp3"),
            item(Some("dup"), "https://e.com/a.mp3"),
            item(Some("dup"), "https://e.com/a.mp3"),
        ]
        .concat();
        let ids = feed_ids(&items);
        let unique: std::collections::HashSet<_> = ids.iter().collect();
        assert_eq!(unique.len(), 3);
        assert_eq!(ids, feed_ids(&items));
    }

    #[test]
    fn prepending_item_keeps_existing_ids_with_duplicate_guid() {
        let old = [
            item(Some("dup"), "https://e.com/b.mp3"),
            item(Some("dup"), "https://e.com/a.mp3"),
        ]
        .concat();
        let new = format!("{}{}", item(Some("dup"), "https://e.com/c.mp3"), old);
        let old_ids = feed_ids(&old);
        let new_ids = feed_ids(&new);
        assert_eq!(&new_ids[1..], &old_ids[..]);
        assert!(!old_ids.contains(&new_ids[0]));
    }

    #[test]
    fn prepending_item_keeps_existing_ids_with_duplicate_guid_and_url() {
        let same = item(Some("dup"), "https://e.com/a.mp3");
        let old = same.repeat(2);
        let new = same.repeat(3);
        let old_ids = feed_ids(&old);
        let new_ids = feed_ids(&new);
        assert_eq!(&new_ids[1..], &old_ids[..]);
        let unique: std::collections::HashSet<_> = new_ids.iter().collect();
        assert_eq!(unique.len(), 3);
    }

    #[test]
    fn missing_guid_keeps_url_fallback_id() {
        let ids = feed_ids(&item(None, "https://e.com/a.mp3"));
        let expected = format!("url:{:x}", Sha256::digest(b"https://e.com/a.mp3"));
        assert_eq!(ids, vec![expected]);
    }

    #[test]
    fn extension_from_content_type_then_url() {
        let url = reqwest::Url::parse("https://example.com/path/file.weird").unwrap();
        assert_eq!(extension_for(Some("audio/mpeg"), &url), "mp3");
        assert_eq!(extension_for(Some("image/jpeg"), &url), "jpg");
        // Type inconnu -> extension de l'URL.
        let url_mp3 = reqwest::Url::parse("https://example.com/a/b.mp3?x=1").unwrap();
        assert_eq!(
            extension_for(Some("application/octet-stream"), &url_mp3),
            "mp3"
        );
    }

    #[test]
    fn validate_remote_url_scheme() {
        assert!(validate_remote_url("file:///etc/passwd").is_err());
        assert!(validate_remote_url("ftp://example.com/x").is_err());
        assert!(validate_remote_url("https://example.com/feed.xml").is_ok());
    }

    #[test]
    fn sanitize_stem_handles_bad_chars_and_length() {
        assert_eq!(sanitize_stem("a/b\\c:d?"), "a_b_c_d_");
        assert_eq!(sanitize_stem("   "), "episode");
        assert!(sanitize_stem(&"x".repeat(200)).chars().count() <= 80);
    }
}

//! Listing d'une URL YouTube via `yt-dlp -J --flat-playlist` (rapide : ne résout
//! pas les formats). Le parsing JSON est isolé (`parse_list_json`, pur et testé) ;
//! l'exécution du binaire reste fine.

use crate::support::user_message;
use crate::support::user_message::codes;
use std::collections::{HashMap, HashSet};
use std::path::Path;
use std::time::Duration;

use serde_json::Value;

use super::error::{classify_failure, YoutubeError};
use super::info_cache;
use super::process::run_command_with_timeout;
use super::tool::{pace_analysis, ToolMode, Ytdlp, SLEEP_REQUESTS};
use super::{YoutubeAudioLanguages, YoutubeList, YoutubeVideo};

/// Taille fixe d'une page. La borne protège chaque appel sans imposer de
/// plafond global : l'UI peut demander autant de pages que nécessaire.
pub(super) const LIST_PAGE_SIZE: usize = 400;
const LIST_TIMEOUT: Duration = Duration::from_secs(120);
const AUDIO_LANGUAGE_TIMEOUT: Duration = Duration::from_secs(5 * 60);
/// Lots courts : chaque vidéo coûte plusieurs requêtes espacées de
/// `SLEEP_REQUESTS`, et un blocage doit interrompre l'analyse au plus tôt.
const AUDIO_LANGUAGE_CHUNK_SIZE: usize = 10;

/// Valide qu'une URL est bien une URL YouTube (HTTP/HTTPS sur un domaine YouTube).
/// Évite d'utiliser yt-dlp comme téléchargeur générique d'un site arbitraire.
pub(super) fn validate_youtube_url(url: &str) -> Result<(), String> {
    let parsed = reqwest::Url::parse(url.trim()).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::YOUTUBE_INVALID_URL)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "URL invalide : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err(
            user_message::UserMessage::new(codes::YOUTUBE_URL_SCHEME_REFUSED)
                .with_detail("Seules les URL http/https sont autorisées.".to_string())
                .into_transport(),
        );
    }
    let host = parsed.host_str().unwrap_or("").to_ascii_lowercase();
    let ok = host == "youtu.be"
        || host == "youtube.com"
        || host.ends_with(".youtube.com")
        || host == "youtube-nocookie.com"
        || host.ends_with(".youtube-nocookie.com");
    if ok {
        Ok(())
    } else {
        Err(
            user_message::UserMessage::new(codes::YOUTUBE_URL_HOST_INVALID)
                .with_detail("Cette adresse n'est pas une URL YouTube.".to_string())
                .into_transport(),
        )
    }
}

pub fn fetch_list(
    home: &Path,
    output_dir: &Path,
    custom: Option<&str>,
    url: &str,
    page: usize,
    mode: ToolMode,
    emit: &dyn Fn(&str),
) -> Result<YoutubeList, YoutubeError> {
    let natural_series_order = is_channel_source(url)?;
    let listing_url = normalize_listing_url(url)?;
    let (start, end_with_sentinel) = page_window(page, LIST_PAGE_SIZE)?;
    let (ytdlp, tools) = Ytdlp::prepare_for(mode, home, custom, emit)?;

    emit(&{
        let _msg_page = (page).to_string();
        user_message::UserMessage::new(codes::YOUTUBE_READING_VIDEOS_PAGE)
            .param("page", user_message::transport_param(_msg_page.clone()))
            .with_detail(format!(
                "Lecture des vidéos — page {_msg_page}…",
                _msg_page = user_message::transport_detail(&_msg_page)
            ))
            .into_transport()
    });
    let mut cmd = ytdlp.command();
    cmd.args([
        "-J",
        "--flat-playlist",
        "--playlist-items",
        &format!("{}:{}", start, end_with_sentinel),
        &listing_url,
    ]);

    let output = run_command_with_timeout(
        cmd,
        LIST_TIMEOUT,
        codes::YOUTUBE_READING_SERVICE_LABEL_TRANSPORT,
    )?;
    if !output.status.success() {
        return Err(classify_failure(
            &String::from_utf8_lossy(&output.stderr),
            codes::YOUTUBE_YTDLP_URL_READ_FAILED_TRANSPORT,
        ));
    }

    // Une vidéo seule est déjà analysée en entier : son téléchargement pourra
    // réutiliser cette analyse.
    info_cache::store(&info_cache::info_dir(output_dir), &output.stdout);
    let value: Value = serde_json::from_slice(&output.stdout).map_err(|_| {
        user_message::UserMessage::new(codes::YOUTUBE_YTDLP_RESPONSE_JSON_INVALID)
            .with_detail("Réponse yt-dlp illisible (JSON invalide).".to_string())
            .into_transport()
    })?;
    let mut list = parse_list_json(value, page, LIST_PAGE_SIZE);
    list.tools = tools;
    if natural_series_order {
        reorder_numbered_series(&mut list.videos);
        let first_source_index = page
            .saturating_sub(1)
            .saturating_mul(LIST_PAGE_SIZE)
            .saturating_add(1);
        assign_selection_keys(&mut list.videos, first_source_index);
    }
    if list.videos.is_empty() {
        return Err(
            user_message::UserMessage::new(codes::YOUTUBE_USABLE_VIDEO_MISSING)
                .with_detail("Aucune vidéo exploitable trouvée pour cette URL.".to_string())
                .into_transport()
                .into(),
        );
    }
    Ok(list)
}

/// Résout les formats uniquement pour les vidéos retenues par l'utilisateur.
/// Le listing initial reste ainsi plat et rapide, même pour une grosse chaîne.
/// Plusieurs URL sont traitées par un même processus yt-dlp pour amortir son
/// démarrage, avec des lots bornés pour éviter une ligne de commande excessive.
///
/// Chaque analyse est conservée pour le téléchargement qui suit
/// (`info_cache`). Un blocage de YouTube interrompt l'analyse aussitôt : les
/// lots suivants ne feraient que le prolonger.
pub fn fetch_audio_languages(
    home: &Path,
    output_dir: &Path,
    custom: Option<&str>,
    video_urls: &[String],
    emit: &dyn Fn(&str),
) -> Result<Vec<YoutubeAudioLanguages>, YoutubeError> {
    let mut seen_urls = HashSet::new();
    let mut urls = Vec::new();
    for url in video_urls {
        validate_youtube_url(url)?;
        let trimmed = url.trim();
        if seen_urls.insert(trimmed.to_string()) {
            urls.push(trimmed.to_string());
        }
    }
    if urls.is_empty() {
        return Ok(Vec::new());
    }

    let ytdlp = Ytdlp::prepare(home, custom, emit)?;
    let info_dir = info_cache::info_dir(output_dir);
    let mut resolved = Vec::new();
    let mut last_error = None;
    let mut analyzed = 0;

    for chunk in urls.chunks(AUDIO_LANGUAGE_CHUNK_SIZE) {
        emit(&{
            let _msg_analyzed = (analyzed).to_string();
            let _msg_urls = (urls.len()).to_string();
            user_message::UserMessage::new(codes::YOUTUBE_ANALYZING_AUDIO_TRACKS)
                .param(
                    "analyzed",
                    user_message::transport_param(_msg_analyzed.clone()),
                )
                .param("urls", user_message::transport_param(_msg_urls.clone()))
                .with_detail(format!(
                    "Analyse des pistes audio ({_msg_analyzed}/{_msg_urls})…",
                    _msg_analyzed = user_message::transport_detail(&_msg_analyzed),
                    _msg_urls = user_message::transport_detail(&_msg_urls)
                ))
                .into_transport()
        });
        pace_analysis();
        let mut cmd = ytdlp.command();
        cmd.args([
            "--dump-json",
            "--no-playlist",
            "--ignore-errors",
            "--sleep-requests",
            SLEEP_REQUESTS,
            "--",
        ]);
        cmd.args(chunk);
        analyzed += chunk.len();

        match run_command_with_timeout(
            cmd,
            AUDIO_LANGUAGE_TIMEOUT,
            codes::YOUTUBE_AUDIO_ANALYSIS_LABEL_TRANSPORT,
        ) {
            Ok(output) => {
                for line in output.stdout.split(|byte| *byte == b'\n') {
                    info_cache::store(&info_dir, line);
                }
                let mut parsed = parse_audio_language_lines(&output.stdout);
                if !output.status.success() {
                    let failure = classify_failure(
                        &String::from_utf8_lossy(&output.stderr),
                        codes::YOUTUBE_AUDIO_TRACK_ANALYSIS_IMPOSSIBLE_TRANSPORT,
                    );
                    if failure.is_blocked() {
                        return Err(failure);
                    }
                    if parsed.is_empty() {
                        last_error = Some(failure);
                    }
                }
                resolved.append(&mut parsed);
            }
            Err(error) => last_error = Some(error.into()),
        }
    }

    if resolved.is_empty() {
        if let Some(error) = last_error {
            return Err(error);
        }
    }
    Ok(resolved)
}

pub(super) fn parse_audio_language_lines(output: &[u8]) -> Vec<YoutubeAudioLanguages> {
    output
        .split(|byte| *byte == b'\n')
        .filter_map(|line| serde_json::from_slice::<Value>(line).ok())
        .filter_map(|value| {
            let id = value.get("id").and_then(Value::as_str)?.to_string();
            Some(YoutubeAudioLanguages {
                id,
                languages: audio_language_codes(&value),
            })
        })
        .collect()
}

/// Une playlist explicite porte un ordre éditorial que Story Studio ne doit pas
/// modifier. Une chaîne, en revanche, est listée via ses uploads : YouTube peut
/// y publier les parties d'une même histoire dans un ordre différent de leur
/// numérotation, auquel cas une correction locale est utile.
pub(super) fn is_channel_source(url: &str) -> Result<bool, String> {
    validate_youtube_url(url)?;
    let parsed = reqwest::Url::parse(url.trim()).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::YOUTUBE_INVALID_URL)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "URL invalide : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    let path = parsed.path().trim_end_matches('/');
    let has_playlist = parsed
        .query_pairs()
        .any(|(key, value)| key == "list" && !value.is_empty());
    let is_video = parsed
        .host_str()
        .is_some_and(|host| host.eq_ignore_ascii_case("youtu.be"))
        || path == "/watch"
        || path == "/shorts"
        || path.starts_with("/shorts/");
    Ok(!has_playlist && !is_video && path != "/playlist")
}

/// Les URL racine de chaîne sont multi-playlists dans yt-dlp (vidéos, Shorts,
/// directs). Les convertir vers l'onglet Vidéos rend les indices de page
/// continus. Un onglet explicitement fourni par l'utilisateur reste inchangé.
pub(super) fn normalize_listing_url(url: &str) -> Result<String, String> {
    validate_youtube_url(url)?;
    let mut parsed = reqwest::Url::parse(url.trim()).map_err(|e| {
        let _msg_error = (e).to_string();
        user_message::UserMessage::new(codes::YOUTUBE_INVALID_URL)
            .param("error", user_message::transport_param(_msg_error.clone()))
            .with_detail(format!(
                "URL invalide : {_msg_error}",
                _msg_error = user_message::transport_detail(&_msg_error)
            ))
            .into_transport()
    })?;
    let segments: Vec<_> = parsed
        .path_segments()
        .map(|parts| parts.filter(|part| !part.is_empty()).collect())
        .unwrap_or_default();

    // Les chaînes identifiées par UC ont une playlist d'uploads canonique UU.
    // Elle reste disponible pour les chaînes « Topic », qui n'ont pas toujours
    // d'onglet /videos, et fournit une liste plate adaptée à la pagination.
    let channel_id = match segments.as_slice() {
        ["channel", id] | ["channel", id, "featured"] if id.starts_with("UC") => {
            Some((*id).to_string())
        }
        _ => None,
    };
    if let Some(channel_id) = channel_id {
        let uploads_id = format!("UU{}", &channel_id[2..]);
        parsed.set_path("/playlist");
        parsed
            .query_pairs_mut()
            .clear()
            .append_pair("list", &uploads_id);
        parsed.set_fragment(None);
        return Ok(parsed.to_string());
    }

    let is_handle_root = matches!(segments.as_slice(), [handle] if handle.starts_with('@'));
    let is_legacy_root = matches!(
        segments.as_slice(),
        [kind, _] if matches!(*kind, "channel" | "c" | "user")
    );
    let is_featured_tab = matches!(
        segments.as_slice(),
        [handle, "featured"] if handle.starts_with('@')
    ) || matches!(
        segments.as_slice(),
        [kind, _, "featured"] if matches!(*kind, "channel" | "c" | "user")
    );

    if is_handle_root || is_legacy_root || is_featured_tab {
        let base_segments = if is_featured_tab {
            &segments[..segments.len() - 1]
        } else {
            &segments[..]
        };
        parsed.set_path(&format!("/{}/videos", base_segments.join("/")));
        parsed.set_query(None);
        parsed.set_fragment(None);
    }

    Ok(parsed.to_string().trim_end_matches('/').to_string())
}

/// Renvoie la plage inclusive comprise par yt-dlp. La borne haute inclut une
/// entrée sentinelle, retirée du résultat, afin de calculer `has_next` sans
/// connaître la taille totale de la source.
pub(super) fn page_window(page: usize, page_size: usize) -> Result<(usize, usize), String> {
    if page == 0 || page_size == 0 {
        return Err(
            user_message::UserMessage::new(codes::YOUTUBE_REQUESTED_YOUTUBE_PAGE_INVALID)
                .with_detail("La page YouTube demandée est invalide.".to_string())
                .into_transport(),
        );
    }
    let start = page
        .checked_sub(1)
        .and_then(|index| index.checked_mul(page_size))
        .and_then(|offset| offset.checked_add(1))
        .ok_or_else(|| {
            user_message::UserMessage::new(codes::YOUTUBE_REQUESTED_PAGE_LIMIT)
                .with_detail("La page YouTube demandée est trop éloignée.".to_string())
                .into_transport()
        })?;
    let end_with_sentinel = start.checked_add(page_size).ok_or_else(|| {
        user_message::UserMessage::new(codes::YOUTUBE_REQUESTED_PAGE_LIMIT)
            .with_detail("La page YouTube demandée est trop éloignée.".to_string())
            .into_transport()
    })?;
    Ok((start, end_with_sentinel))
}

/// Convertit la sortie JSON yt-dlp en `YoutubeList` (pur, sans réseau). Gère la
/// vidéo seule, la playlist et la chaîne (playlists imbriquées aplaties).
pub(super) fn parse_list_json(value: Value, page: usize, page_size: usize) -> YoutubeList {
    let title = channel_tab_title(&value).or_else(|| {
        value
            .get("title")
            .and_then(Value::as_str)
            .map(str::to_string)
    });
    let image_url = pick_image(&value, value.get("id").and_then(Value::as_str));

    let mut videos = Vec::new();
    let collect_limit = page_size.saturating_add(1);
    if value.get("entries").is_some() {
        collect_entries(&value, collect_limit, &mut videos);
    } else if let Some(video) = build_video(&value) {
        videos.push(video);
    }

    let has_next = videos.len() > page_size;
    if has_next {
        videos.truncate(page_size);
    }
    let first_source_index = page
        .saturating_sub(1)
        .saturating_mul(page_size)
        .saturating_add(1);
    assign_selection_keys(&mut videos, first_source_index);
    let title = title
        .or_else(|| videos.first().map(|v| v.title.clone()))
        .unwrap_or_else(|| "YouTube".to_string());

    YoutubeList {
        title,
        image_url,
        videos,
        page,
        page_size,
        has_next,
        tools: None,
    }
}

fn channel_tab_title(value: &Value) -> Option<String> {
    let webpage_url = value.get("webpage_url").and_then(Value::as_str)?;
    let path = reqwest::Url::parse(webpage_url).ok()?.path().to_string();
    let is_media_tab = ["/videos", "/shorts", "/streams"]
        .iter()
        .any(|suffix| path.ends_with(suffix));
    is_media_tab
        .then(|| value.get("channel").and_then(Value::as_str))
        .flatten()
        .filter(|title| !title.is_empty())
        .map(str::to_string)
}

/// Parcourt `entries`, aplatit les playlists imbriquées et s'arrête à la borne
/// de la page courante (sentinelle comprise).
fn collect_entries(node: &Value, limit: usize, out: &mut Vec<YoutubeVideo>) {
    let Some(entries) = node.get("entries").and_then(Value::as_array) else {
        return;
    };
    for entry in entries {
        if out.len() >= limit {
            return;
        }
        if entry.get("entries").is_some() {
            collect_entries(entry, limit, out);
        } else if let Some(video) = build_video(entry) {
            out.push(video);
        }
    }
}

fn build_video(entry: &Value) -> Option<YoutubeVideo> {
    let id = entry.get("id").and_then(Value::as_str);
    let audio_url = watch_url(entry, id)?;
    let title = entry
        .get("title")
        .and_then(Value::as_str)
        .map(str::to_string)
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "Vidéo".to_string());
    let audio_languages_resolved = entry.get("formats").and_then(Value::as_array).is_some();
    Some(YoutubeVideo {
        id: id.unwrap_or("").to_string(),
        selection_key: String::new(),
        source_index: 0,
        title,
        audio_url,
        duration: format_duration(entry.get("duration").and_then(Value::as_f64)),
        image_url: pick_image(entry, id),
        audio_languages: audio_language_codes(entry),
        audio_languages_resolved,
    })
}

fn audio_language_codes(entry: &Value) -> Vec<String> {
    let mut seen = HashSet::new();
    entry
        .get("formats")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|format| {
            format.get("vcodec").and_then(Value::as_str) == Some("none")
                && format
                    .get("acodec")
                    .and_then(Value::as_str)
                    .is_some_and(|codec| codec != "none")
        })
        .filter_map(|format| format.get("language").and_then(Value::as_str))
        .map(str::trim)
        .filter(|language| !language.is_empty())
        .filter(|language| seen.insert((*language).to_string()))
        .map(str::to_string)
        .collect()
}

fn assign_selection_keys(videos: &mut [YoutubeVideo], first_source_index: usize) {
    for (index, video) in videos.iter_mut().enumerate() {
        let source_index = first_source_index.saturating_add(index);
        video.source_index = source_index;
        video.selection_key = if video.id.is_empty() {
            format!("video-{}", source_index)
        } else {
            format!("{}#{}", video.id, source_index)
        };
    }
}

fn numbered_series_part(title: &str) -> Option<(String, u64)> {
    let trimmed = title.trim();
    let digit_start = trimmed
        .char_indices()
        .rev()
        .take_while(|(_, ch)| ch.is_ascii_digit())
        .last()
        .map(|(index, _)| index)?;
    if digit_start == trimmed.len() {
        return None;
    }
    let part_number = trimmed[digit_start..].parse().ok()?;
    let mut prefix = trimmed[..digit_start].trim_end();
    for marker in ["n°", "nº", "no", "#"] {
        if prefix.to_ascii_lowercase().ends_with(marker) {
            prefix = prefix[..prefix.len() - marker.len()].trim_end();
            break;
        }
    }

    let lower = prefix.to_ascii_lowercase();
    let marker = ["partie", "part", "pt.", "pt"]
        .into_iter()
        .find(|marker| lower.ends_with(marker))?;
    let marker_start = prefix.len().checked_sub(marker.len())?;
    if marker_start > 0
        && prefix[..marker_start]
            .chars()
            .next_back()
            .is_some_and(|ch| ch.is_alphanumeric())
    {
        return None;
    }
    let base = prefix[..marker_start]
        .trim_end_matches(|ch: char| {
            ch.is_whitespace() || matches!(ch, '-' | '_' | '.' | '–' | '—')
        })
        .trim();
    if base.is_empty() {
        return None;
    }
    let key = base
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase();
    Some((key, part_number))
}

/// Réordonne uniquement les emplacements déjà occupés par une même série.
/// Les vidéos sans numéro et les différentes histoires gardent donc exactement
/// leur position relative dans la liste d'uploads.
pub(super) fn reorder_numbered_series(videos: &mut [YoutubeVideo]) {
    let mut positions_by_series: HashMap<String, Vec<usize>> = HashMap::new();
    for (index, video) in videos.iter().enumerate() {
        if let Some((series, _)) = numbered_series_part(&video.title) {
            positions_by_series.entry(series).or_default().push(index);
        }
    }

    for positions in positions_by_series
        .values()
        .filter(|positions| positions.len() > 1)
    {
        let mut ordered: Vec<_> = positions
            .iter()
            .map(|index| videos[*index].clone())
            .collect();
        ordered.sort_by_key(|video| {
            numbered_series_part(&video.title)
                .map(|(_, part)| part)
                .unwrap_or(u64::MAX)
        });
        for (position, video) in positions.iter().zip(ordered) {
            videos[*position] = video;
        }
    }
}

/// URL de visionnage : `url`/`webpage_url` si déjà http(s), sinon reconstruite
/// depuis l'identifiant.
fn watch_url(entry: &Value, id: Option<&str>) -> Option<String> {
    for key in ["url", "webpage_url"] {
        if let Some(u) = entry.get(key).and_then(Value::as_str) {
            if u.starts_with("http://") || u.starts_with("https://") {
                return Some(u.to_string());
            }
        }
    }
    id.filter(|s| !s.is_empty())
        .map(|id| format!("https://www.youtube.com/watch?v={}", id))
}

/// Miniature : champ `thumbnail`, sinon dernière de `thumbnails`, sinon miniature
/// canonique reconstruite depuis l'identifiant.
fn pick_image(node: &Value, id: Option<&str>) -> Option<String> {
    if let Some(thumb) = node.get("thumbnail").and_then(Value::as_str) {
        if !thumb.is_empty() {
            return Some(thumb.to_string());
        }
    }
    if let Some(url) = node
        .get("thumbnails")
        .and_then(Value::as_array)
        .and_then(|arr| {
            arr.iter()
                .rev()
                .find_map(|t| t.get("url").and_then(Value::as_str))
        })
    {
        return Some(url.to_string());
    }
    id.filter(|s| !s.is_empty())
        .map(|id| format!("https://i.ytimg.com/vi/{}/hqdefault.jpg", id))
}

/// Secondes → `M:SS` (ou `H:MM:SS`). `None`/0 → `None`.
pub(super) fn format_duration(seconds: Option<f64>) -> Option<String> {
    let total = seconds.filter(|s| *s >= 1.0)? as u64;
    let (h, m, s) = (total / 3600, (total % 3600) / 60, total % 60);
    if h > 0 {
        Some(format!("{}:{:02}:{:02}", h, m, s))
    } else {
        Some(format!("{}:{:02}", m, s))
    }
}
